<script setup lang="ts">
import {computed,reactive,ref} from 'vue';import {useRouter} from 'vue-router';import PageHeader from '../../components/common/PageHeader.vue';import SegmentTabs from '../../components/common/SegmentTabs.vue';import SearchFilterBar from '../../components/common/SearchFilterBar.vue';import EmptyState from '../../components/common/EmptyState.vue';import DetailDrawer from '../../components/common/DetailDrawer.vue';import EntityTable from '../../components/common/EntityTable.vue';import StatusTag from '../../components/common/StatusTag.vue';import {workbenchRepository} from '../../services/workbenchRepository';import type {WorkOrder} from '../../types';
const router=useRouter();const data=ref(workbenchRepository.load());const tab=ref('all');const keyword=ref('');const selected=ref<WorkOrder|null>(null);const formOpen=ref(false);const feedback=ref('');const form=reactive({title:'',description:'',goal:'',productLine:'',customer:'',priority:'',source:''});
const rows=computed(()=>data.value.workOrders.filter(item=>(tab.value==='all'||item.status===tab.value)&&Object.values(item).join(' ').toLowerCase().includes(keyword.value.toLowerCase())));const persist=()=>workbenchRepository.save(data.value);const openDetail=(value:Record<string,unknown>)=>{selected.value=value as unknown as WorkOrder;feedback.value=''};
const add=()=>{if(!form.title||!form.priority||!form.source)return;data.value.workOrders.unshift({id:`WO-${Date.now()}`,code:`POOL-${new Date().getFullYear()}-${String(data.value.workOrders.length+36).padStart(3,'0')}`,title:form.title,description:form.description,goal:form.goal,productLine:form.productLine,customer:form.customer,priority:form.priority,source:form.source,status:'待评审',createdAt:new Date().toISOString().slice(0,10)});persist();formOpen.value=false;Object.assign(form,{title:'',description:'',goal:'',productLine:'',customer:'',priority:'',source:''})};
const transition=(status:WorkOrder['status'])=>{if(!selected.value)return;selected.value.status=status;persist();feedback.value=`工单已更新为“${status}”`};const convert=(route:string)=>{transition('已转任务');router.push(route)};const cell=(row:Record<string,unknown>,index:number)=>[row.code,row.title,row.productLine,row.priority,row.source,row.status,row.createdAt][index]??'—';
</script>
<template><section class="workbench-view"><PageHeader eyebrow="WORK ORDER CENTER" title="工单中心" description="统一接收客户、销售、运维和内部规划需求，并流转到研发。"><template #actions><button class="primary" @click="formOpen=true">提交工单</button></template></PageHeader><div class="metric-grid compact"><article><span>工单总数</span><strong>{{data.workOrders.length}}</strong><small>条</small></article><article><span>待评审</span><strong>{{data.workOrders.filter(x=>x.status==='待评审').length}}</strong><small>条</small></article><article><span>已采纳</span><strong>{{data.workOrders.filter(x=>x.status==='已采纳').length}}</strong><small>条</small></article><article><span>已转任务</span><strong>{{data.workOrders.filter(x=>x.status==='已转任务').length}}</strong><small>条</small></article></div><SegmentTabs v-model="tab" :items="[{key:'all',label:'全部'},{key:'待评审',label:'待评审'},{key:'已采纳',label:'已采纳'},{key:'已转任务',label:'已转任务'}]"/><SearchFilterBar v-model="keyword" placeholder="搜索工单编号、标题、客户或产品线" :count="rows.length"/><EntityTable v-if="rows.length" :columns="['工单编号','标题','产品线','优先级','来源','状态','提交时间']" :rows="rows" :cell="cell" @select="openDetail"/><EmptyState v-else title="暂无匹配工单" description="请调整搜索条件或提交新的工单。"/><DetailDrawer :open="Boolean(selected)" :title="selected?.title||'工单详情'" @close="selected=null"><template v-if="selected"><div class="detail-actions"><StatusTag :status="selected.status"/><StatusTag :status="selected.priority"/></div><dl class="detail-list"><dt>工单编号</dt><dd>{{selected.code}}</dd><dt>来源</dt><dd>{{selected.source}}</dd><dt>产品线</dt><dd>{{selected.productLine||'—'}}</dd><dt>客户</dt><dd>{{selected.customer||'—'}}</dd><dt>问题描述</dt><dd>{{selected.description||'—'}}</dd><dt>预期目标</dt><dd>{{selected.goal||'—'}}</dd><dt>提交时间</dt><dd>{{selected.createdAt}}</dd></dl><p v-if="feedback" class="form-feedback">{{feedback}}</p><div class="form-actions vertical"><button class="secondary" @click="transition('已采纳')">采纳工单</button><button class="secondary" @click="transition('已拒绝')">拒绝工单</button><button class="primary" @click="convert('/app/prod_req_tasks')">转为需求任务</button><button class="primary" @click="convert('/app/prod_rd_tasks')">转为研发任务</button><button class="primary" @click="convert('/app/prod_bugs')">转为缺陷</button></div></template></DetailDrawer><DetailDrawer :open="formOpen" title="提交工单" @close="formOpen=false"><form class="work-item-form" @submit.prevent="add"><label>工单标题<input v-model="form.title" required placeholder="请输入工单标题"/></label><label>问题描述<textarea v-model="form.description" rows="4" placeholder="请描述问题或需求背景"/></label><label>预期目标<textarea v-model="form.goal" rows="3" placeholder="请输入期望达到的结果"/></label><div class="form-grid"><label>产品线<input v-model="form.productLine" placeholder="请输入所属产品线"/></label><label>客户<input v-model="form.customer" placeholder="请输入关联客户"/></label></div><div class="form-grid"><label>优先级<select v-model="form.priority" required><option value="" disabled>请选择优先级</option><option>P0-紧急阻断</option><option>P1-高优</option><option>P2-普通</option><option>P3-低优</option></select></label><label>工单来源<select v-model="form.source" required><option value="" disabled>请选择工单来源</option><option>客户反馈</option><option>销售商机</option><option>内部规划</option><option>运维反馈</option></select></label></div><div class="form-actions"><button type="button" class="secondary" @click="formOpen=false">取消</button><button class="primary">提交工单</button></div></form></DetailDrawer></section></template>
